    31→describe("buildColdStartBreadcrumb", () => {
    32→  it("builds breadcrumb for workspace section", () => {
    33→    const stack = buildColdStartBreadcrumb("/workspace/my-proj/chat");
    34→    expect(stack).toHaveLength(3);
    35→    expect(stack[0].label).toBe("Workspaces");
    36→    expect(stack[0].href).toBe("/workspace");
    37→    expect(stack[1].label).toBe("my-proj");
    38→    expect(stack[1].href).toBe("/workspace/my-proj");
    39→    expect(stack[2].label).toBe("Chat");
    40→    expect(stack[2].href).toBe("/workspace/my-proj/chat");
    41→  });
    42→
    43→  it("expands rest param segments", () => {
    44→    const stack = buildColdStartBreadcrumb("/workspace/x/pages/first/second/third");
    45→    expect(stack).toHaveLength(6);
    46→    // Ancestors
    47→    expect(stack[0].href).toBe("/workspace");
    48→    expect(stack[1].href).toBe("/workspace/x");
    49→    expect(stack[2].href).toBe("/workspace/x/pages");
    50→    // Rest intermediates (label = last segment only)
    51→    expect(stack[3].label).toBe("First");
    52→    expect(stack[3].href).toBe("/workspace/x/pages/first");
    53→    expect(stack[4].label).toBe("Second");
    54→    expect(stack[4].href).toBe("/workspace/x/pages/first/second");
    55→    // Current
    56→    expect(stack[5].label).toBe("Third");
    57→    expect(stack[5].href).toBe("/workspace/x/pages/first/second/third");
    58→  });
    59→
    60→  it("handles single-segment rest param (no expansion)", () => {
    61→    const stack = buildColdStartBreadcrumb("/workspace/x/pages/single");
    62→    expect(stack).toHaveLength(4); // workspace, x, pages, single
    63→    expect(stack[3].label).toBe("Single");
    64→  });
    65→
    66→  it("applies headers override to current node", () => {
    67→    const stack = buildColdStartBreadcrumb("/workspace/x/agent/gpt", { label: "GPT-4o" });
    68→    const last = stack[stack.length - 1];
    69→    expect(last.label).toBe("GPT-4o");
    70→  });
    71→
    72→  it("returns empty for unknown URL", () => {
    73→    expect(buildColdStartBreadcrumb("/totally/unknown")).toEqual([]);
    74→  });
    75→
    76→  it("builds settings breadcrumb with parent", () => {
    77→    const stack = buildColdStartBreadcrumb("/settings/general");
    78→    expect(stack).toHaveLength(2);
    79→    expect(stack[0].label).toBe("Settings");
    80→    expect(stack[1].label).toBe("General");
    81→  });
    82→});
